import { NextResponse } from "next/server";
import { startOfMonth, endOfMonth, subDays } from "date-fns";

import { assertRole, getSession } from "@/lib/auth";
import { runQuery, runSingle } from "@/lib/db";

type TipoJornada = "completa" | "media" | "permiso_con_goce" | "permiso_sin_goce" | "vacaciones" | "licencia_medica" | "falta" | "feriado";

export async function GET() {
    try {
        const session = await getSession();
        assertRole(session, ["company_admin", "superadmin"]);

        const companyId = session.companyId;
        if (!companyId && session.role !== "superadmin") {
            return NextResponse.json({ error: "Empresa no encontrada" }, { status: 400 });
        }

        const now = new Date();
        const monthStart = startOfMonth(now);
        const monthEnd = endOfMonth(now);
        const daysInMonth = monthEnd.getDate();
        const todayDay = now.getDate();

        // Obtener todos los empleados activos
        const employees = await runQuery<{ id: string; nombreCompleto: string }>(
            `SELECT id, "nombreCompleto" FROM "Employee" WHERE "companyId" = $1 AND "isActive" = true`,
            [companyId]
        );

        const totalEmployees = employees.length;
        if (totalEmployees === 0) {
            return NextResponse.json({
                asistenciaPorcentaje: 0,
                diasTrabajados: 0,
                diasHabiles: 0,
                topFaltas: [],
                tendenciaSemanal: [],
                alertas: []
            });
        }

        // Obtener registros del mes
        const records = await runQuery<{
            employeeId: string;
            fecha: string;
            tipoJornada: TipoJornada;
        }>(
            `SELECT "employeeId", "fecha", "tipoJornada" 
             FROM "TimeRecord" 
             WHERE "companyId" = $1 AND "fecha" >= $2 AND "fecha" <= $3`,
            [companyId, monthStart, monthEnd]
        );

        // Calcular días trabajados (tipos que cuentan como asistencia)
        const tiposPresentismo: TipoJornada[] = ["completa", "media", "permiso_con_goce", "feriado", "licencia_medica"];
        const diasTrabajados = records.filter(r => tiposPresentismo.includes(r.tipoJornada)).length;
        const diasHabiles = totalEmployees * todayDay; // días hábiles esperados hasta hoy
        const asistenciaPorcentaje = diasHabiles > 0 ? Math.round((diasTrabajados / diasHabiles) * 100) : 0;

        // Top 5 trabajadores con más faltas
        const faltasPorEmpleado: Record<string, number> = {};
        records.forEach(r => {
            if (r.tipoJornada === "falta" || r.tipoJornada === "permiso_sin_goce") {
                faltasPorEmpleado[r.employeeId] = (faltasPorEmpleado[r.employeeId] || 0) + 1;
            }
        });

        const topFaltas = Object.entries(faltasPorEmpleado)
            .map(([id, count]) => ({
                id,
                nombre: employees.find(e => e.id === id)?.nombreCompleto || "Desconocido",
                faltas: count
            }))
            .sort((a, b) => b.faltas - a.faltas)
            .slice(0, 5);

        // Tendencia semanal (últimos 7 días)
        const tendenciaSemanal: { dia: string; asistencia: number; faltas: number }[] = [];
        for (let i = 6; i >= 0; i--) {
            const fecha = subDays(now, i);
            const fechaStr = fecha.toISOString().split("T")[0];
            const diasSemana = ["Dom", "Lun", "Mar", "Mié", "Jue", "Vie", "Sáb"];
            const diaLabel = diasSemana[fecha.getDay()];

            const recordsDia = records.filter(r => r.fecha.toString().startsWith(fechaStr));
            const asistencia = recordsDia.filter(r => tiposPresentismo.includes(r.tipoJornada)).length;
            const faltas = recordsDia.filter(r => r.tipoJornada === "falta").length;

            tendenciaSemanal.push({ dia: diaLabel, asistencia, faltas });
        }

        // Alertas de ausentismo (empleados con 3+ faltas)
        const alertas = Object.entries(faltasPorEmpleado)
            .filter(([, count]) => count >= 3)
            .map(([id, count]) => ({
                empleadoId: id,
                nombre: employees.find(e => e.id === id)?.nombreCompleto || "Desconocido",
                mensaje: `${count} faltas este mes`,
                tipo: count >= 5 ? "critico" : "advertencia"
            }));

        return NextResponse.json({
            asistenciaPorcentaje,
            diasTrabajados,
            diasHabiles,
            totalEmpleados: totalEmployees,
            topFaltas,
            tendenciaSemanal,
            alertas
        });

    } catch (error) {
        console.error("Error en KPIs:", error);
        return NextResponse.json({ error: "Error al obtener KPIs" }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { z } from "zod";
import crypto from "node:crypto";

import { runSingle, runQuery } from "@/lib/db";

// Validar API key desde headers
const validateApiKey = (request: Request): boolean => {
    const apiKey = request.headers.get("x-api-key");
    const expectedKey = process.env.SYNC_API_KEY;

    if (!expectedKey) {
        console.warn("SYNC_API_KEY no configurada en .env");
        return false;
    }

    return apiKey === expectedKey;
};

const workerSchema = z.object({
    companyName: z.string().min(1), // Nombre de la empresa para buscarla
    nombreCompleto: z.string().min(1),
    rut: z.string().optional().nullable(),
    email: z.string().email(),
    sueldoMensual: z.number().optional().nullable(),
});

export async function POST(request: Request) {
    try {
        // Validar autenticación
        if (!validateApiKey(request)) {
            return NextResponse.json({ error: "No autorizado" }, { status: 401 });
        }

        const body = await request.json();
        const data = workerSchema.parse(body);

        // Buscar la empresa por nombre
        const company = await runSingle<{ id: string }>(
            `SELECT id FROM "Company" WHERE "name" = $1`,
            [data.companyName]
        );

        if (!company) {
            return NextResponse.json({
                error: "Empresa no encontrada",
                details: `No existe empresa con nombre: ${data.companyName}`
            }, { status: 404 });
        }

        // Buscar si ya existe el usuario por email
        let user = await runSingle<{ id: string }>(
            `SELECT id FROM "User" WHERE "email" = $1`,
            [data.email]
        );

        if (!user) {
            // Crear usuario
            const userId = crypto.randomUUID();
            const defaultPassword = crypto.randomBytes(16).toString("hex"); // Temporal

            await runSingle(
                `INSERT INTO "User" ("id", "email", "passwordHash", "role", "createdAt", "updatedAt")
                 VALUES ($1, $2, $3, 'worker', NOW(), NOW())`,
                [userId, data.email, defaultPassword]
            );

            user = { id: userId };
        }

        // Buscar si ya existe el empleado en esta empresa
        const existingEmployee = await runSingle<{ id: string }>(
            `SELECT id FROM "Employee" WHERE "userId" = $1 AND "companyId" = $2`,
            [user.id, company.id]
        );

        if (existingEmployee) {
            // Actualizar empleado existente
            await runSingle(
                `UPDATE "Employee" SET 
                    "nombreCompleto" = $1,
                    "rut" = COALESCE($2, "rut"),
                    "sueldoMensual" = COALESCE($3, "sueldoMensual"),
                    "updatedAt" = NOW()
                 WHERE "id" = $4`,
                [data.nombreCompleto, data.rut, data.sueldoMensual, existingEmployee.id]
            );

            return NextResponse.json({
                success: true,
                action: "updated",
                employeeId: existingEmployee.id
            });
        }

        // Crear nuevo empleado
        const employeeId = crypto.randomUUID();

        await runSingle(
            `INSERT INTO "Employee" 
                ("id", "companyId", "userId", "nombreCompleto", "rut", "sueldoMensual", "isActive", "createdAt", "updatedAt")
             VALUES ($1, $2, $3, $4, $5, $6, true, NOW(), NOW())`,
            [employeeId, company.id, user.id, data.nombreCompleto, data.rut, data.sueldoMensual]
        );

        return NextResponse.json({
            success: true,
            action: "created",
            employeeId,
            userId: user.id
        });

    } catch (error) {
        if (error instanceof z.ZodError) {
            return NextResponse.json({ error: "Datos inválidos", details: error.issues }, { status: 400 });
        }
        console.error("Error en sync/worker:", error);
        return NextResponse.json({ error: "Error al sincronizar trabajador" }, { status: 500 });
    }
}

import { NextResponse } from "next/server";
import { assertRole, getSession } from "@/lib/auth";
import { listEmployeesByCompany, updateEmployee } from "@/lib/repos/employees";

const normalize = (s: string) =>
    s.toLowerCase().trim().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

export async function POST(request: Request) {
    try {
        const session = await getSession();
        assertRole(session, ["company_admin"]);

        const body = await request.json();
        const { workers } = body; // Array of { nombre, rut, email, sueldo }

        if (!Array.isArray(workers)) {
            return NextResponse.json({ error: "Formato inválido" }, { status: 400 });
        }

        const currentEmployees = await listEmployeesByCompany(session.companyId!);
        let updatedCount = 0;
        let notFoundCount = 0;

        for (const item of workers) {
            // Intentar buscar por email (si viene)
            let match = null;
            if (item.email) {
                match = currentEmployees.find(e =>
                    normalize(e.user.email) === normalize(item.email)
                );
            }

            // Si no, buscar por nombre
            if (!match && item.nombre) {
                match = currentEmployees.find(e =>
                    normalize(e.nombreCompleto) === normalize(item.nombre)
                );
            }

            if (match) {
                // Actualizar campos si vienen
                const updates: any = {};
                if (item.rut) updates.rut = item.rut;
                if (item.sueldo) updates.sueldoMensual = Number(item.sueldo);
                if (item.afp) updates.afp = item.afp;
                if (item.salud) updates.salud = item.salud;

                if (Object.keys(updates).length > 0) {
                    await updateEmployee(match.id, updates);
                    updatedCount++;
                }
            } else {
                notFoundCount++;
            }
        }

        return NextResponse.json({
            success: true,
            updated: updatedCount,
            skipped: notFoundCount
        });

    } catch (error) {
        console.error("Error importing workers:", error);
        return NextResponse.json(
            { error: "Error interno al procesar archivo" },
            { status: 500 }
        );
    }
}

import { useState, useRef } from "react";
import * as XLSX from "xlsx";
import { FileSpreadsheet } from "lucide-react";

export function BulkWorkerImport({ onSuccess }: { onSuccess: () => void }) {
    const [loading, setLoading] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);

    const processFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setLoading(true);
        try {
            const buffer = await file.arrayBuffer();
            const workbook = XLSX.read(buffer, { type: "array" });
            const sheetName = workbook.SheetNames[0];
            const sheet = workbook.Sheets[sheetName];

            // Leer como array de arrays para buscar headers
            const rawData = XLSX.utils.sheet_to_json(sheet, { header: 1 }) as any[][];

            // Buscar fila de encabezados
            let headerRowIndex = -1;
            const headerMap: Record<string, number> = {};

            for (let i = 0; i < rawData.length; i++) {
                const row = rawData[i];
                const rowStr = row.map(c => String(c).toUpperCase().trim());

                if (rowStr.includes("NOMBRE") || rowStr.includes("RUT") || rowStr.includes("TRABAJADOR")) {
                    headerRowIndex = i;
                    rowStr.forEach((col, idx) => {
                        headerMap[col] = idx;
                    });
                    break;
                }
            }

            if (headerRowIndex === -1) {
                const debugRows = rawData.slice(0, 5).map(r => JSON.stringify(r)).join("\n");
                alert(`No se encontró fila de encabezados.\nBuscando: NOMBRE, RUT o TRABAJADOR.\n\nContenido leído:\n${debugRows}`);
                setLoading(false);
                return;
            }

            const workers = [];
            for (let i = headerRowIndex + 1; i < rawData.length; i++) {
                const row = rawData[i];
                if (!row || row.length === 0) continue;

                const getVal = (keys: string[]) => {
                    for (const k of keys) {
                        if (headerMap[k] !== undefined) return row[headerMap[k]];
                    }
                    return undefined;
                };

                const nombre = getVal(["NOMBRE", "NOMBRE COMPLETO", "TRABAJADOR", "NOMBRES"]);
                const rut = getVal(["RUT", "IDENTIFICADOR", "R.U.T."]);
                const email = getVal(["EMAIL", "CORREO", "MAIL", "CORREO ELECTRONICO"]);
                const sueldo = getVal(["SUELDO", "SUELDO BASE", "SUELDO MENSUAL"]);
                const afp = getVal(["AFP", "PREVISION", "A.F.P."]);
                const salud = getVal(["SALUD", "ISAPRE", "FONASA", "PREVISION SALUD"]);

                if (nombre || email) {
                    workers.push({ nombre, rut, email, sueldo, afp, salud });
                }
            }

            if (workers.length === 0) {
                alert("No se encontraron registros de trabajadores después de los encabezados.");
                setLoading(false);
                return;
            }

            const res = await fetch("/api/workers/import", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ workers })
            });

            if (!res.ok) throw new Error("Error en servidor");
            const result = await res.json();
            alert(`Proceso finalizado exitosamente.\n\nregistros actualizados: ${result.updated}\nregistros omitidos: ${result.skipped}`);
            onSuccess();

        } catch (err) {
            alert("Error al procesar el archivo. Revisa el formato.");
            console.error(err);
        } finally {
            setLoading(false);
            if (inputRef.current) inputRef.current.value = "";
        }
    };

    return (
        <>
            <input
                type="file"
                ref={inputRef}
                className="hidden"
                accept=".xlsx,.xls"
                onChange={processFile}
            />
            <button
                disabled={loading}
                onClick={() => inputRef.current?.click()}
                className="flex items-center gap-2 rounded-lg bg-emerald-600 px-4 py-2 text-sm font-medium text-white hover:bg-emerald-500 disabled:opacity-50 transition-colors"
            >
                <FileSpreadsheet className="h-4 w-4" />
                {loading ? "Leyendo..." : "Importar Excel"}
            </button>
        </>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Fuel, Truck, Plus, Loader2, Calendar, DollarSign } from "lucide-react";

type FuelType = "bencina_93" | "bencina_95" | "bencina_97" | "diesel" | "electrico" | "otro";

type Vehicle = {
    id: string;
    patente: string;
    marca: string | null;
    modelo: string | null;
    anio: number | null;
    tipoCombustible: FuelType;
    isActive: boolean;
};

type FuelRecordWithDetails = {
    id: string;
    vehicleId: string;
    fecha: string;
    litros: number;
    kilometraje: number | null;
    tipoCombustible: FuelType;
    costoTotal: number | null;
    precioLitro: number | null;
    estacion: string | null;
    observaciones: string | null;
    patente: string;
    employeeName: string | null;
};

const fuelTypeLabels: Record<FuelType, string> = {
    bencina_93: "Bencina 93",
    bencina_95: "Bencina 95",
    bencina_97: "Bencina 97",
    diesel: "Diesel",
    electrico: "Eléctrico",
    otro: "Otro",
};

export function FuelPanel() {
    const [vehicles, setVehicles] = useState<Vehicle[]>([]);
    const [records, setRecords] = useState<FuelRecordWithDetails[]>([]);
    const [loading, setLoading] = useState(true);
    const [showVehicleForm, setShowVehicleForm] = useState(false);
    const [showRecordForm, setShowRecordForm] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState<string | null>(null);

    // Vehicle form state
    const [patente, setPatente] = useState("");
    const [marca, setMarca] = useState("");
    const [modelo, setModelo] = useState("");
    const [anio, setAnio] = useState("");
    const [vehicleFuelType, setVehicleFuelType] = useState<FuelType>("bencina_95");

    // Record form state
    const [selectedVehicle, setSelectedVehicle] = useState("");
    const [fecha, setFecha] = useState(new Date().toISOString().split("T")[0]);
    const [litros, setLitros] = useState("");
    const [kilometraje, setKilometraje] = useState("");
    const [recordFuelType, setRecordFuelType] = useState<FuelType>("bencina_95");
    const [costoTotal, setCostoTotal] = useState("");
    const [estacion, setEstacion] = useState("");
    const [observaciones, setObservaciones] = useState("");

    const fetchData = async () => {
        try {
            const [vehiclesRes, recordsRes] = await Promise.all([
                fetch("/api/vehicles"),
                fetch("/api/fuel-records"),
            ]);
            const vehiclesData = await vehiclesRes.json();
            const recordsData = await recordsRes.json();
            setVehicles(vehiclesData.vehicles || []);
            setRecords(recordsData.records || []);
        } catch {
            setError("Error al cargar datos");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const handleCreateVehicle = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        try {
            const res = await fetch("/api/vehicles", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    patente,
                    marca: marca || undefined,
                    modelo: modelo || undefined,
                    anio: anio ? parseInt(anio) : undefined,
                    tipoCombustible: vehicleFuelType,
                }),
            });
            const data = await res.json();
            if (!res.ok) throw new Error(data.error);
            setSuccess("Vehículo creado exitosamente");
            setShowVehicleForm(false);
            setPatente("");
            setMarca("");
            setModelo("");
            setAnio("");
            fetchData();
        } catch (err) {
            setError(err instanceof Error ? err.message : "Error al crear vehículo");
        }
    };

    const handleCreateRecord = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        try {
            const res = await fetch("/api/fuel-records", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    vehicleId: selectedVehicle,
                    fecha,
                    litros: parseFloat(litros),
                    kilometraje: kilometraje ? parseInt(kilometraje) : undefined,
                    tipoCombustible: recordFuelType,
                    costoTotal: costoTotal ? parseFloat(costoTotal) : undefined,
                    estacion: estacion || undefined,
                    observaciones: observaciones || undefined,
                }),
            });
            const data = await res.json();
            if (!res.ok) throw new Error(data.error);
            setSuccess("Carga de combustible registrada");
            setShowRecordForm(false);
            setLitros("");
            setKilometraje("");
            setCostoTotal("");
            setEstacion("");
            setObservaciones("");
            fetchData();
        } catch (err) {
            setError(err instanceof Error ? err.message : "Error al registrar carga");
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center p-12">
                <Loader2 className="h-8 w-8 animate-spin text-violet-500" />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {/* Mensajes */}
            {error && (
                <div className="rounded-lg bg-red-500/20 border border-red-500/40 p-4 text-red-200">
                    {error}
                </div>
            )}
            {success && (
                <div className="rounded-lg bg-green-500/20 border border-green-500/40 p-4 text-green-200">
                    {success}
                </div>
            )}

            {/* Stats Cards */}
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
                <div className="rounded-xl bg-white/5 backdrop-blur-sm border border-white/10 p-5">
                    <div className="flex items-center gap-3">
                        <div className="rounded-lg bg-violet-500/20 p-2.5">
                            <Truck className="h-5 w-5 text-violet-400" />
                        </div>
                        <div>
                            <p className="text-2xl font-bold text-white">{vehicles.length}</p>
                            <p className="text-sm text-gray-400">Vehículos</p>
                        </div>
                    </div>
                </div>
                <div className="rounded-xl bg-white/5 backdrop-blur-sm border border-white/10 p-5">
                    <div className="flex items-center gap-3">
                        <div className="rounded-lg bg-cyan-500/20 p-2.5">
                            <Fuel className="h-5 w-5 text-cyan-400" />
                        </div>
                        <div>
                            <p className="text-2xl font-bold text-white">{records.length}</p>
                            <p className="text-sm text-gray-400">Cargas registradas</p>
                        </div>
                    </div>
                </div>
                <div className="rounded-xl bg-white/5 backdrop-blur-sm border border-white/10 p-5">
                    <div className="flex items-center gap-3">
                        <div className="rounded-lg bg-emerald-500/20 p-2.5">
                            <DollarSign className="h-5 w-5 text-emerald-400" />
                        </div>
                        <div>
                            <p className="text-2xl font-bold text-white">
                                ${records.reduce((sum, r) => sum + (r.costoTotal || 0), 0).toLocaleString("es-CL")}
                            </p>
                            <p className="text-sm text-gray-400">Costo total</p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Actions */}
            <div className="flex gap-3">
                <button
                    onClick={() => setShowVehicleForm(!showVehicleForm)}
                    className="flex items-center gap-2 rounded-lg bg-violet-600 px-4 py-2.5 text-sm font-medium text-white hover:bg-violet-500 transition-colors"
                >
                    <Plus className="h-4 w-4" />
                    Nuevo Vehículo
                </button>
                <button
                    onClick={() => setShowRecordForm(!showRecordForm)}
                    className="flex items-center gap-2 rounded-lg bg-cyan-600 px-4 py-2.5 text-sm font-medium text-white hover:bg-cyan-500 transition-colors"
                    disabled={vehicles.length === 0}
                >
                    <Fuel className="h-4 w-4" />
                    Registrar Carga
                </button>
            </div>

            {/* Vehicle Form */}
            {showVehicleForm && (
                <form onSubmit={handleCreateVehicle} className="rounded-xl bg-white/5 backdrop-blur-sm border border-white/10 p-6 space-y-4">
                    <h3 className="text-lg font-semibold text-white">Nuevo Vehículo</h3>
                    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
                        <div>
                            <label className="block text-sm text-gray-400 mb-1">Patente *</label>
                            <input
                                type="text"
                                value={patente}
                                onChange={(e) => setPatente(e.target.value.toUpperCase())}
                                required
                                placeholder="ABCD12"
                                className="w-full rounded-lg bg-white/10 border border-white/20 px-4 py-2.5 text-white placeholder-gray-500 focus:border-violet-500 focus:ring-1 focus:ring-violet-500"
                            />
                        </div>
                        <div>
                            <label className="block text-sm text-gray-400 mb-1">Marca</label>
                            <input
                                type="text"
                                value={marca}
                                onChange={(e) => setMarca(e.target.value)}
                                placeholder="Toyota"
                                className="w-full rounded-lg bg-white/10 border border-white/20 px-4 py-2.5 text-white placeholder-gray-500 focus:border-violet-500 focus:ring-1 focus:ring-violet-500"
                            />
                        </div>
                        <div>
                            <label className="block text-sm text-gray-400 mb-1">Modelo</label>
                            <input
                                type="text"
                                value={modelo}
                                onChange={(e) => setModelo(e.target.value)}
                                placeholder="Hilux"
