            </p>
          </div>

          {/* Filtro Principal + Herramientas */}
          <div className="w-full lg:w-96 flex flex-col gap-3">
            <label className="text-xs font-semibold text-gray-400 uppercase tracking-wider block">Filtrar por Trabajador</label>

            <select
