              </h3>

              <div className="space-y-4">
                <label className="block">
                  <span className="text-xs font-semibold text-gray-400 block mb-1.5">Trabajador</span>
                  <select
                    value={form.employeeId}
                    onChange={(event) =>
                      setForm((prev) => ({ ...prev, employeeId: event.target.value }))
                    }
